package cn.mop.api;

import cn.mop.domain.DomainException;
import cn.mop.domain.backup.BackupRunState;
import cn.mop.domain.backup.BackupRunState.*;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Pure contract-fixed bookkeeping. No SSH, storage, scheduler, database or ticket is simulated as integration. */
class BackupRunStateTest {
    final UUID tenant=UUID.fromString("55000000-0000-4000-8000-000000000001"),asset=UUID.fromString("66000000-0000-4000-8000-000000000001");
    final Instant t=Instant.parse("2026-10-03T12:00:00Z");
    BackupRunState queued(){return BackupRunState.queued(tenant,asset,t);}
    BackupRunState running(){return queued().start(0,t);}
    StoredVersion stored(Instant when){return new StoredVersion(tenant,asset,UUID.randomUUID(),"a".repeat(64),100,when);}
    @Test void queueDoesNotClaimAttemptSuccessOrFinalFailure(){var q=queued();assertEquals(State.QUEUED,q.state());assertEquals(t,q.nextAttemptAt());assertNull(q.lastAttemptAt());assertNull(q.lastSuccessAt());assertNull(q.finishedAt());assertNull(q.finalRunFailureCount());assertEquals(0,q.knownFailedAttemptCount());assertEquals(0,q.version());}
    @Test void contractHasOneInitialAttemptAndTwoRetriesAtTenMinuteIntervals(){assertEquals(3,BackupRunState.MAX_ATTEMPTS);assertEquals(Duration.ofMinutes(10),BackupRunState.RETRY_DELAY);var r=running().fail(1,t.plusSeconds(2),Failure.READ_TIMEOUT);assertEquals(State.RETRY_WAIT,r.state());assertEquals(t.plusSeconds(602),r.nextAttemptAt());assertEquals(1,r.knownFailedAttemptCount());assertNull(r.finalRunFailureCount());assertNull(r.finishedAt());}
    @Test void noEarlyRetryButExactBoundaryAllowed(){var r=running().fail(1,t,Failure.READ_TIMEOUT);assertThrows(DomainException.class,()->r.start(2,t.plusSeconds(599)));var next=r.start(2,t.plusSeconds(600));assertEquals(State.RUNNING,next.state());assertEquals(2,next.attempts().size());assertEquals(t.plusSeconds(600),next.lastAttemptAt());}
    @Test void thirdKnownFailureIsTerminalAndNoFourthAttempt(){var r=running();for(int i=0;i<3;i++){r=r.fail(r.version(),t.plusSeconds(i*600L),Failure.READ_TIMEOUT);if(i<2)r=r.start(r.version(),t.plusSeconds((i+1)*600L));}assertEquals(State.FAILED,r.state());assertEquals(3,r.knownFailedAttemptCount());assertEquals(1,r.finalRunFailureCount());assertEquals(t.plusSeconds(1200),r.finishedAt());assertNull(r.nextAttemptAt());var terminal=r;assertThrows(DomainException.class,()->terminal.start(terminal.version(),t.plusSeconds(1800)));}
    @Test void successfulRetryKeepsPriorFailedAttemptButFinalRunIsNotFailed(){var r=running().fail(1,t,Failure.STORAGE_FAILED).start(2,t.plusSeconds(600));r=r.succeed(3,t.plusSeconds(603),stored(t.plusSeconds(602)));assertEquals(State.SUCCEEDED,r.state());assertEquals(1,r.knownFailedAttemptCount());assertEquals(0,r.finalRunFailureCount());assertEquals(t.plusSeconds(603),r.lastSuccessAt());assertEquals(Failure.STORAGE_FAILED,r.attempts().get(0).failure());assertEquals(Outcome.SUCCEEDED,r.attempts().get(1).outcome());}
    @Test void unknownNeverCountsAsFailureOrEnablesBlindRetry(){var r=running().markUnknown(1,t.plusSeconds(1));assertEquals(State.RUNNING,r.state());assertTrue(r.reconciliationRequired());assertEquals(0,r.knownFailedAttemptCount());assertNull(r.finalRunFailureCount());assertNull(r.nextAttemptAt());assertThrows(DomainException.class,()->r.start(2,t.plusSeconds(900)));}
    @Test void unknownReconcilesSuccessInSameAttemptWithoutRereadingDevice(){var r=running().markUnknown(1,t.plusSeconds(1));r=r.succeed(2,t.plusSeconds(5),stored(t.plusSeconds(2)));assertEquals(1,r.attempts().size());assertEquals(State.SUCCEEDED,r.state());assertFalse(r.reconciliationRequired());}
    @Test void unknownReconciledFailureStartsDelayAtConfirmedFailure(){var r=running().markUnknown(1,t.plusSeconds(1)).fail(2,t.plusSeconds(100),Failure.STORAGE_FAILED);assertEquals(t.plusSeconds(700),r.nextAttemptAt());assertEquals(1,r.knownFailedAttemptCount());}
    @Test void lossAfterEarlierFailureDoesNotCreateFinalRunFailure(){var r=running().fail(1,t,Failure.READ_TIMEOUT).start(2,t.plusSeconds(600)).markUnknown(3,t.plusSeconds(601));assertEquals(1,r.knownFailedAttemptCount());assertNull(r.finalRunFailureCount());assertEquals(2,r.attempts().size());}
    @Test void unknownObservationTimeMustBeMonotonic(){var r=running().markUnknown(1,t.plusSeconds(10));assertThrows(DomainException.class,()->r.markUnknown(2,t.plusSeconds(9)));assertThrows(DomainException.class,()->r.fail(2,t.plusSeconds(9),Failure.READ_TIMEOUT));assertEquals(3,r.markUnknown(2,t.plusSeconds(10)).version());}
    @Test void successRequiresNonNullStorageReferenceForExactTenantAndDevice(){var r=running();assertThrows(DomainException.class,()->r.succeed(1,t,null));for(StoredVersion wrong:List.of(new StoredVersion(UUID.randomUUID(),asset,UUID.randomUUID(),"a".repeat(64),1,t),new StoredVersion(tenant,UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),1,t)))assertEquals(404,assertThrows(DomainException.class,()->r.succeed(1,t,wrong)).status);}
    @Test void storedReferenceCannotPredateAttemptOrClaimFuturePersistence(){var r=running();assertThrows(DomainException.class,()->r.succeed(1,t.plusSeconds(1),stored(t.minusSeconds(1))));assertThrows(DomainException.class,()->r.succeed(1,t.plusSeconds(1),stored(t.plusSeconds(2))));}
    @Test void invalidHashSizeAndFractionalTimeRejectedWithoutEchoingInputs(){var error=assertThrows(DomainException.class,()->new StoredVersion(tenant,asset,UUID.randomUUID(),"SYNTHETIC_SECRET",1,t));assertFalse(error.getMessage().contains("SYNTHETIC"));assertThrows(DomainException.class,()->new StoredVersion(tenant,asset,UUID.randomUUID(),"a".repeat(64),0,t));assertThrows(DomainException.class,()->queued().start(0,t.plusNanos(1)));assertThrows(DomainException.class,()->BackupRunState.queued(null,asset,t));}
    @Test void earlyInitialAttemptAndStaleLogicalVersionRejected(){var q=queued();assertThrows(DomainException.class,()->q.start(0,t.minusMillis(1)));assertEquals("VERSION_CONFLICT",assertThrows(DomainException.class,()->q.start(1,t)).code);var r=running();assertThrows(DomainException.class,()->r.fail(0,t,Failure.READ_TIMEOUT));}
    @Test void activeAttemptCannotBeStartedAgainOrCompletedTwice(){var r=running();assertThrows(DomainException.class,()->r.start(1,t));var success=r.succeed(1,t,stored(t));assertThrows(DomainException.class,()->success.fail(2,t,Failure.STORAGE_FAILED));assertThrows(DomainException.class,()->success.markUnknown(2,t));assertThrows(DomainException.class,()->success.succeed(2,t,stored(t)));}
    @Test void immutableSnapshotsAndHistoryCannotBeRewritten(){var initial=queued();var run=initial.start(0,t);var failed=run.fail(1,t,Failure.READ_TIMEOUT);assertEquals(State.QUEUED,initial.state());assertEquals(State.RUNNING,run.state());assertEquals(State.RETRY_WAIT,failed.state());assertThrows(UnsupportedOperationException.class,()->failed.attempts().clear());}
    @Test void attemptConstructorRejectsInconsistentTerminalFacts(){assertThrows(DomainException.class,()->new Attempt(1,t,t,null,Outcome.FAILED,Failure.READ_TIMEOUT,null));assertThrows(DomainException.class,()->new Attempt(1,t,t,t,Outcome.SUCCEEDED,null,null));assertThrows(DomainException.class,()->new Attempt(1,t,t,null,Outcome.RUNNING,Failure.READ_TIMEOUT,null));assertThrows(DomainException.class,()->new Attempt(4,t,t,null,Outcome.RUNNING,null,null));}
    @Test void missingFailureClassificationIsNotAssumed(){assertThrows(DomainException.class,()->running().fail(1,t,null));assertNull(running().lastSuccessAt());}
    @Test void retryDateOverflowRejectedWithoutPartialTransition(){Instant end=Instant.parse("9999-12-31T23:59:59.999Z");var r=BackupRunState.queued(tenant,asset,end).start(0,end);assertThrows(DomainException.class,()->r.fail(1,end,Failure.READ_TIMEOUT));assertEquals(State.RUNNING,r.state());}
    @Test void q22RemainsNullAndAutomaticP3IsBlockedForEveryRunState(){var active=running();var failed=active;for(int i=0;i<3;i++){failed=failed.fail(failed.version(),t.plusSeconds(i*600L),Failure.READ_TIMEOUT);if(i<2)failed=failed.start(failed.version(),t.plusSeconds((i+1)*600L));}for(var r:List.of(queued(),active,active.markUnknown(1,t),active.fail(1,t,Failure.READ_TIMEOUT),active.succeed(1,t,stored(t)),failed)){assertNull(r.failureCountSemantics());assertEquals("CONFIG_PENDING",r.automaticTicketStatus());assertFalse(r.automaticTicketAllowed());}}
}
